"""Publish only completed, audited reporting-r2; no partial-result reporting."""
import argparse,json
from pathlib import Path


def interval(point,bounds):return f'{point:.2f} [{bounds[0]:.2f}, {bounds[1]:.2f}]'
def qtext(q):return '/'.join(f'{q[k]:.1f}' for k in ('p50','p95','p99','max'))

def main():
    p=argparse.ArgumentParser();p.add_argument('--results',type=Path,required=True);a=p.parse_args();r=json.loads(a.results.read_text());dest=Path(__file__).parent
    assert r['paired_seeds']==600 and not r['smoke_excluded'] and r['checks']['games']==2400
    gc_report=json.loads((dest/'gc-maintenance.json').read_text())
    assert all(gc_report['arms'][arm]['games']==600 for arm in r['arms'])
    arms=r['arms'];speed=r['minimum_speed'];qualified=speed['minimum_tested_qualified_ratio'];point=speed['point_interpolated_crossing_ratio']
    speedtext=f'{qualified:.2f}× fleet per-core speed' if qualified is not None else 'no tested speed through1.0× qualifies'
    lines=['# K-v2 honest-latency deadline sweep','',f"Completed {r['utc']}. **2,400 terminal reporting games;600 fresh paired seeds per arm**, sealed v1 opponent, symmetric d=27/capacity1. Five decks/25 matchups/both seats;12 seeds per cell. Draws are separate; loss means v1 wins. No Mac/live/heldout access.",'','| Arm | W/L/D | Loss %,95% CI | Paired loss change vs K0-200,pp,95% CI | Cutoff %,95% CI |','|---|---:|---:|---:|---:|']
    for name,v in arms.items():lines.append(f"| {name} | {v['wins']}/{v['losses']}/{v['draws']} | {interval(v['loss_pct'],v['loss_ci_pct'])} | {interval(v['loss_change_pp'],v['loss_change_ci_pp'])} | {interval(v['cutoff_pct'],v['cutoff_ci_pct'])} |")
    lines[3:3]=['', f"V200 improves loss by {abs(arms['V200']['loss_change_pp']):.2f}pp versus K0-200; V160 still clears the−10pp paired confidence gate. V120 loses {arms['V120']['loss_pct']:.2f}% with {arms['V120']['cutoff_pct']:.2f}% cutoffs, showing a steep cliff between160 and120ms. Minimum tested speed for the performance gate is0.80×; point interpolation0.760× is descriptive.", '', '**The strict return bound is not qualified.** The final smoke passed, but reporting recorded16/15/7 W cut returns beyond deadline+8ms for V200/V160/V120, plus3 for K0-200. The cancellation drain fix therefore does not establish the requested bound on every full-pipeline decision. All late actions are charged; no source changes or reruns followed these outcomes. Mac deployment also remains gated on unmeasured maintenance/poll delays.']
    lines+=['','| Arm | Wall p50/p95/p99/max,ms | Overruns / decisions | Overrun %,95% CI | Positive overrun p50/p95/p99/max,ms | Cut returns > deadline+8ms |','|---|---:|---:|---:|---:|---:|']
    for name,v in arms.items():lines.append(f"| {name} | {qtext(v['wall_ms'])} | {v['overrun_count']}/{v['decisions']} | {interval(v['overrun_pct'],v['overrun_ci_pct'])} | {qtext(v['positive_overrun_ms'])} | {v['cut_past_deadline_plus_reserve_count']} |")
    lines+=['', '| Arm | Cut decisions | Cut wall p50/p95/p99/max,ms | Cut returns > deadline | Cut returns > deadline+8ms |', '|---|---:|---:|---:|---:|']
    for name,v in arms.items():
        cut_count=round(v['cutoff_pct']*v['decisions']/100)
        lines.append(f"| {name} | {cut_count} | {qtext(v['cut_wall_ms'])} | {v['cut_past_deadline_count']} | {v['cut_past_deadline_plus_reserve_count']} |")
    lines+=['','Positive-overrun quantiles condition on wall exceeding that arm’s deadline; zero means none observed. Every positive overrun is recorded in raw decision stats and charged as ceil(overrun×20) ticks. A selected play remains reserved immediately and executes at observation tick+27+late ticks; timed waits and own availability also shift. Opponent cadence stays unchanged. No late action is applied for free.','', '| Deadline reduction | Loss increase,pp per40ms,95% CI | pp/ms |','|---|---:|---:|']
    for name,v in r['slopes'].items():lines.append(f"| {name} | {interval(v['loss_increase_pp_per_40ms'],v['ci_pp_per_40ms'])} | {v['pp_per_ms']:.4f} |")
    ls=r['linear_loss_vs_deadline'];lines+=['',f"Least-squares loss-versus-deadline slope across120/160/200ms: **{interval(ls['pp_per_ms'],ls['ci_pp_per_ms'])}pp/ms**. Adjacent slopes above expose nonlinearity; a linear fit is descriptive.",'',f"**Minimum supported Mac admission requirement from this sweep: {speedtext}**, using the smallest tested deadline whose upper paired95% loss-change CI≤−10pp. Minimum tested point-estimate ratio: {speed['minimum_tested_point_ratio']:.2f}×. "+(f"Piecewise point interpolation crosses−10pp at **{point:.3f}×**; this is an estimate, not a qualified speed." if point is not None else 'The point crossing is not bracketed by this grid; no extrapolation is claimed.'),'','The labels0.8× and0.6× are budget equivalence:160/200 and120/200. Keeping the8ms reserve fixed means scoring-budget ratios are152/192=0.792 and112/192=0.583. The sweep changes compute headroom, while preparation/return timing and overrun-to-tick conversion run at actual fleet speed. It is not an underclock experiment. It measures one hypothetical public belief root. Actual Mac/four-root performance remains unknown and must pass loaded E4 qualification; the supported requirement is a lower-bound deployment condition, not a measured Mac guarantee.','', '**Return-path implementation:** the collector uses a remaining-time-bounded wait, admits only complete pre-cutoff scores, signals cancellation and cancels queued work, and returns without drains. Frozen native44874fd6 checks before each simulation tick. Private roots and immutable worker inputs prevent late mutation of returned scores. No scorer phase/order/horizon/tie/default-policy or combat/native change occurred. The8ms reserve starts from full observation/policy/belief/candidates/root/scoring/submission timing. Residuals beyond deadline+8ms remain visible; the reporting trace does not identify their precise stage or prove an OS cause.','', 'Automatic cyclic GC is deferred during decisions, then restored between decisions/physics steps. Every maintenance pause is metered; whole-game CPU/wall includes its cost. This prevents a non-cancellable Python pause without attributing the unreproduced smoke-r2 residuals to GC. Loaded Mac qualification must measure maintenance and packet gaps as well as decision calls. [GC guard](GC-GUARD.md).','', 'An additional upstream tail appeared in the first excluded smoke:165ms belief preparation inside a191ms decision. The owned exact preparation fix operates in4096-row blocks, suspends private partial histories at cutoff, and commits only complete updates. It resumes before newer events; no preparation work leaves the timer. All arms receive the same fix. No-deadline posterior implementation remains frozen. See [amendment](PREPARATION-AMENDMENT.md).','', 'Qualification: exact screen8 actions/candidates/retained scores125/125 for each1/4 threads; one/four equality125/125; native zero-budget root immutability125/125. Exact posterior/weights/cumulative order/resource ledger/sampling/RNG on125 histories for deadlineON andOFF,125/125 each.25 injected-clock/lateness/preparation/GC tests pass. Final excluded smoke-r3:32 terminal games, timing/metadata/seed audits and the cut-return reserve gate passed. Earlier excluded smoke64 plus ten diagnostic games and a zero-terminal aborted reporting admission are retained and excluded. No outcome-based tuning occurred.','', 'Fleet:127x03 only, nice10/SCHED_OTHER; who checked before launch, with nine independent5-core masks on physical0–44 and supervisor45. No SMT; caches/controller48–63/112–127 untouched. K0-200 preserves frozen single-thread scoring while reserving five physical cores, the other arms use four scorer workers. BLAS/Torch/Rayon1; CUDA disabled; caches under/mpac. G STOP-03 was created, its exit receipt and absent PGID were verified before timing; G was never restarted. Owned setsid-f wrapper records PIDs/PGIDs. Final vacate/release receipt is linked in progress.','', 'Reporting seeds4503601807370496+[0,600); excluded smoke4503601817370496+[0,8). [Original frozen seed audit](receipts/seed-audit-freeze-e546e181.json) and [supplement](seed-audit.json) prove disjoint K/X/G and helper intervals against coordinator plan and freeze records. Plan freezee546e181; initial cancellation implementatione01dffe5; exact preparation amendment75e2513d; GC guard83a7faea; nice10 correction is in [operational note](OPERATIONAL-NOTE.md). Original frozen plan bytes are preserved.','', 'CIs use one shared5000-resample paired-seed bootstrap, seed2026101002, pointwise95% percentile intervals without adjustment. Loss contrasts preserve all four seed pairings; cutoff/overrun CIs resample per-game numerator/denominator totals. Every game passes arm/seed/deck/seat/terminal/outcome/deadline/thread/affinity/priority/lateness checks. Full wall distributions include first calls, and exclude blocked polls, five-tick maintenance and opponent calls.','', '[Full counts/CIs/tails/file hashes](results.json), [plan](plan.json), [qualification](receipts/qualification-r2.json), [posterior qualification](receipts/belief-qualification.json), [runtime pin](receipts/runtime-pin-r3.json), [progress and release](PROGRESS.md), [Mac E4 requirements](MAC-E4-V2.md), [interface](INTERFACE.md). Raw games/logs remain03:/mpac/sdicks02/jobs/clasher/k-v2-20261010-r1/reporting-r2.']
    lines+=['', '**Live-deployment caveat: deferred GC maintenance.** The sim meters these pauses in whole-game wall/CPU, but does not advance game ticks or charge them as decision lateness. In live play they can delay the next poll; the loss estimates therefore retain an unquantified deployment penalty. The final excluded smoke already observed maintenance pauses up to152ms.', '', '| Arm | Pauses | Pause p50/p95/p99/max,ms | Pauses/game minute | Pause ms/game minute | Inside decision windows | Live opportunity overlap |', '|---|---:|---:|---:|---:|---:|---|']
    for name,v in gc_report['arms'].items():
        lines.append(f"| {name} | {v['count']} | {qtext(v['pause_ms'])} | {v['count_per_game_minute']:.2f} | {v['pause_ms_per_game_minute']:.2f} | {v['during_decision_window_count']} | Unknown |")
    lines+=['', 'Rates use summed terminal game ticks/1200 as game minutes, rather than simulator wall minutes. Counts cover recorded collections from game setup through the post-extraction snapshot; file writing and inter-game gaps are excluded, and the frozen trace has no finer phase labels. Distributions condition on recorded collections, including short generation0 pauses. No collection occurred inside an own/opponent decision window. **Whether any maintenance pause overlapped a live decision opportunity is unknown**: the trace lacks pause start/end timestamps, scheduled poll deadlines and opportunity/channel state. Zero inside-window collections cannot establish zero delayed polls. [GC counts, generations, distributions, rates and limitations](gc-maintenance.json). Loaded Mac tests must record this overlap explicitly.']
    lines+=['', 'A prose bound in the frozen seed audit overstated the conservative DAgger block; numerical checks used10,000,000 seeds and also verified the actual32,768-seed freeze. [Clarification](receipts/seed-audit-prose-clarification.md). Arbitrarily extended future DAgger allocation needs a new audit against these reporting/smoke/helper intervals.', '', 'Final execution audit verified1,536 pinned runtime files and77 native-source files with zero mismatches; all2,400 terminal files and407,492 decisions passed metadata/lateness checks. Supervisor exited0 at05:04:16Z; no pauses across973 census samples, minimum117.84GiB available. Reporting supervisor/pool PGIDs1718083/1718091 and G PGID1575208 are absent. [Execution/source/vacate receipt](receipts/execution-final.json), [final host census](receipts/host-audit-final.json). The original final host audit failed its persistent-cache-PID assertion because former cache PID1655741 was absent; start/warm audits passed. K-v2 issued no cache/controller signals or affinity changes; that external exit’s time/reason is unknown. The replacement read-only final census records this absence explicitly and establishes owned process vacancy.']
    (dest/'RESULTS.md').write_text('\n'.join(lines)+'\n')
    advancing=[name for name in ('V120','V160','V200') if arms[name]['loss_change_ci_pp'][1]<=-10]
    mac=['# Mac E4 v2 requirements from K-v2','',f"Updated {r['utc']}. Prepared on Linux only; no Mac access/transfer/live change. This owned note supersedes K’s latency/speed assumptions for the fixed K4 comparator. Existing Mac package and its pins remain read-only.",'',f"K-v2 requires **{speedtext}** as the minimum supported budget-equivalent per-core admission condition for at least−10pp versus K0-200 (upper paired95% CI≤−10pp). Tested qualifying cells: {', '.join(advancing) or 'none'}. "+(f"Point interpolation estimates {point:.3f}×, with no qualification below the tested passing cell." if point is not None else 'The grid does not bracket a point crossing; no extrapolation.'),'','1. Build and pin an owned generic arm64 GIL-release/tick-cancellation binary after a separately authorized Mac session. Preserve combat source/templates/Python ABI/compiler/adapter/config pins. Linux native44874fd6 is provenance only.','2. Repeat125-state no-deadline screen8 action/score/root/RNG equality across1/4 workers. Require complete candidate/style/root contributions before common cutoff and original reduction/ties. Include exact preparation posterior/ledger/sample/RNG qualification and cutoff/resume tests, pre-cutoff scores collected late, zero/partial/exact-cutoff/late-worker tests, and late command/wait effects at20Hz.','3. Use one global four-worker scorer pool across the existing four belief roots; do not nest4×4 workers. WAIT/WAIT10 completes across all required roots before plays. Each worker has a private root and stops at its next cancellable simulation tick. Return at scoring cutoff without waiting on worker drains; do not publish partial/late scores or post-return mutable state. Exact public belief preparation must also be resumable/cancellable; do not move it outside the full timer. Defer cyclic GC during critical decisions only, meter its maintenance cost, and verify loaded packet-gap/end-to-end gates account for maintenance.','4. Benchmark per-core throughput against a pinned fleet-equivalent fixed work corpus and measure the complete four-root pipeline with actual perception/emulator load on four uncontended scorer cores. Include cold/warm observation, v1 fallback, belief, candidates, reconstruction, all roots/styles, reduction and real submission in the200ms timer with8ms reserve. Measure p50/p95/p99/max, cutoff/no-complete-play/fallback, every >200ms overrun and >208ms cut return. The one-root fleet sweep does not qualify the four-root Mac pipeline.','5. If throughput is below the minimum supported condition or full pipeline/tail gates fail, K4 has no supported−10pp claim for that Mac session. Report the measured speed and cutoff regime; keep a separately qualified fallback. No new one-core/default/student configuration is authorized here. The frozen K-v2 default remains the polled v1 only when no complete root score exists.','6. Preserve existing formal E4 real-gRPC/frame-to-submission/FPS/gap/command-acceptance/P4 gates and eight-match integration qualification. Loaded replay is insufficient. Account for real late submission in replay/game evaluation; report all overruns, never grant late actions immediate effect.','', 'The deadline sweep holds an8ms reserve, so0.8/0.6 nominal headroom corresponds to0.792/0.583 scoring-budget ratios. Return/preparation and real-time game-tick scaling are not slowed by hardware emulation. The actual minimum Mac per-core speed cannot be measured without Mac access; this note states a supported lower-bound requirement and the loaded qualification needed to use it.','', '[K-v2 results](RESULTS.md), [original Mac package](../../strategy_council_20260928/live-loop/v4/mac-e4-package/RUNBOOK.md).']
    mac+=['', '7. Qualify a GC strategy on the Mac: consider gc.freeze() after representative warmup, followed by tuned generation thresholds and bounded maintenance scheduling. Measure retained memory and peak RSS alongside collection frequency; freezing and threshold changes require the same score/posterior equality qualification. Record every maintenance pause with start/end monotonic timestamps, generation, game tick, scheduled poll deadline, channel availability and decision opportunity. Report count, p50/p95/p99/max, rate per real game minute, overlapping-opportunity count, skipped/delayed polls and pause-to-next-submission delay under actual perception/emulator load. Include maintenance in live end-to-end/FPS/packet-gap gates; moving it outside the decision timer does not satisfy those gates. The Linux study did not use freeze/tuned thresholds and cannot establish zero live opportunity overlap.']
    mac[5:5]=['', '**Performance condition only:**0.80× is the minimum tested budget-equivalent speed meeting the loss gate. It does not qualify deployment. The reporting sweep failed the universal deadline+8ms return bound (16/15/7 W exceedances); full-pipeline latency and maintenance/poll gates must pass on the loaded Mac before admission. Neither drain removal nor the passing smoke proves a hard timing guarantee.']
    gc_requirement=mac.pop()
    gc_index=next(i for i,line in enumerate(mac) if line.startswith('The deadline sweep'))
    mac[gc_index:gc_index]=[gc_requirement,'']
    (dest/'MAC-E4-V2.md').write_text('\n'.join(mac)+'\n')
if __name__=='__main__':main()
